pe=pefile.PE(data=raw,fast_load=True);assert pe.OPTIONAL_HEADER.ImageBase==0x140000000
assert not pe.OPTIONAL_HEADER.DATA_DIRECTORY[5].Size
md=Cs(CS_ARCH_X86,CS_MODE_64)
bodies=[]
def body(rva,size,rows,note):
 data=pe.get_data(rva,size);ins=list(md.disasm(data,rva));assert sum(i.size for i in ins)==size,hex(rva)
 decoded={i.address:(i.mnemonic,i.op_str) for i in ins}
 for a,m,o in rows:assert decoded.get(a)==(m,o),(hex(a),decoded.get(a),(m,o))
 bodies.append((rva,data,note))
body(0x11152a0,0xec,[(0x11152c8,'cmp','word ptr [rcx + 0x3bc], r15w'),(0x11152dd,'mov','word ptr [rdx], ax'),(0x111531c,'mov','r14, qword ptr [rcx + 0xa8]'),(0x1115329,'call','qword ptr [rax + 0x68]'),(0x111532f,'mov','word ptr [rsi], dx'),(0x1115351,'movzx','eax, word ptr [rbp + 0x18]'),(0x1115355,'mov','word ptr [rsi], ax'),(0x111538b,'ret','')],'complete aim target acquisition: void(camera primary*,u16*,vec4*,u8*)')
body(0x111e890,0xea,[(0x111e8c9,'lea','r8, [rcx + 0x3e0]'),(0x111e8d0,'lea','rdx, [rcx + 0x3dc]'),(0x111e8e8,'call','0x11152a0'),(0x111e8ed,'movzx','ecx, word ptr [rsi + 0x3dc]'),(0x111e8f4,'cmp','cx, r14w'),(0x111e953,'xor','al, al')],'complete sole acquisition caller: IDFFFF rejects camera target')
body(0x1114080,0x204,[(0x11140a3,'call','0x111e890'),(0x11140a8,'test','al, al'),(0x1114141,'lea','r9, [rbx + 0x3e0]'),(0x1114162,'call','0x1114610')],'complete camera assist look computation consumes accepted target')
body(0x111d4b0,0x99f,[(0x111d573,'lea','rcx, [rbx - 0x20]'),(0x111d5ad,'call','0x1114080'),(0x111d613,'test','dl, dl'),(0x111de4e,'ret','')],'complete secondary camera look update converts interface to primary for assist')
body(0x1115aa0,0x19a,[(0x1115aad,'mov','rax, qword ptr [rdx]'),(0x1115ab3,'mov','qword ptr [rcx + 0x368], rax'),(0x1115c39,'ret','')],'complete camera owner initialization')
body(0x1113fe0,0x5c,[(0x111401a,'lea','rax, [rip + 0x12a41f7]'),(0x1114021,'mov','qword ptr [rbx], rax'),(0x1114024,'lea','rax, [rip + 0x12a4225]'),(0x111402b,'mov','qword ptr [rbx + 0x20], rax')],'complete factory final camera primary23B8218/secondary23B8250')
assert struct.unpack('<Q',pe.get_data(0x23b8250+0x98,8))[0]==0x14111d4b0
h='// Generated by tools/generate_teammate_targeting_contract.py; do not edit.\n// Exact executable SHA256 '+SHA+'\n#pragma once\n#include <cstddef>\n#include <cstdint>\nnamespace mgscoop::teammate_targeting_contract {\n'
h+='inline constexpr std::uintptr_t target_rva=0x11152a0, caller_return=0x111e8ed, camera_primary_vtable=0x23b8218, camera_secondary_vtable=0x23b8250;\n'
h+='inline constexpr std::size_t camera_owner=0x368, target_id=0x3dc, target_position=0x3e0;\n'
for n,(a,d,t) in enumerate(bodies):h+='// '+t+'\ninline constexpr unsigned char body'+str(n)+'[]={'+','.join(hex(x) for x in d)+'};\n'
h+='struct Body {std::uintptr_t rva;const unsigned char* bytes;std::size_t size;};\ninline constexpr Body bodies[]={\n'
for n,(a,d,t) in enumerate(bodies):h+='{'+hex(a)+',body'+str(n)+',sizeof(body'+str(n)+')},\n'
h+='};\n}\n'
e=json.dumps(dict(executable=str(EXE),sha256=SHA,scope='Natural aim acquisition observe hook; no gameplay proof; filtering remains disabled by default',abi='Windows x64 void(camera primary* RCX,uint16* RDX,vec4* R8,uint8* R9)',bodies=[dict(rva=hex(a),size=len(d),sha256=hashlib.sha256(d).hexdigest(),purpose=t) for a,d,t in bodies]),indent=2)+'\n'
for path,text in [(ROOT/'native/teammate_targeting_contract.hpp',h),(ROOT/'docs/evidence/teammate-targeting-contract-2026-10-09.json',e)]:
 if '--check' in sys.argv:assert path.read_text()==text,str(path)
 else:path.write_text(text)
